# ORIGINAL: O1A's gate (lk-channel evidence/R2 design for O1) — format/2,3 (pl-fmt.c do_format, formatInteger, formatFloat,
# the column machinery, `~@` through the output redirect) against swipl 10.1.19; generated by evidence/O1A/gen_rows.py.
# test/core_lang/test_format_swipl.jl — every `~` directive family and the errors, as clauses of a consulted program (the loader):
#   * cases `t_<id>(R)` run IN ORDER in one database, each wrapped in `catch(Goal, error(SsuE, _), R = raised(SsuE))`; R is the text
#     format/3 wrote to an atom, string, codes or chars sink (the output redirect: tellString / toldString), or the error formal.
#   * Every answer line is swipl's, PINNED (swipl 10.1.19, evidence/O1A/o1a_rows.out, two byte-identical runs); with `swipl` on PATH
#     the live answers are compared with the pins too. UNVERIFIED on the kernel: gate decides (a mismatch is traced, not re-pinned).
#   * `~:d` and `~:f` print the C locale on the kernel (a stream has no locale, D9): their rows pin the kernel's answer, swipl's in the row.
using Test, LogicKernel
const LK = LogicKernel

# TERM TYPES PER CHUNK: REFERENCE — the at context (src/pl-comp.jl, src/pl-wam.jl), built on the term layer; every type in CI and at milestones
include(joinpath(@__DIR__, "..", "term_under_test.jl"))
const _FM = lk_term_type(Union{Int64, Float64, String, BigInt, Rational{BigInt}})
_fms(x) = lk_sym(_FM, Symbol(x))

_fm_codes(s::String) = "[" * join(Int.(collect(s)), ",") * "]"
"A term as the driver's `enc/1` writes it: `V<i>` by first occurrence, atoms and functors by their codes."
function _fm_enc(t::_FM, seen::Vector{UInt64}=UInt64[])::String
    k = kind(t)
    if k === VAR
        i = findfirst(==(var_key(t)), seen)
        if i === nothing
            push!(seen, var_key(t))
            i = length(seen)
        end
        return "V$(i - 1)"
    elseif k === SYM
        return is_nil(t) ? "nil" : "a" * _fm_codes(sym_text(t))
    elseif k === GND
        v = lk_value(t)
        v isa AbstractString && return "s" * _fm_codes(String(v))
        v isa Integer && return "i$v"
        v isa Rational && return "q$(numerator(v))r$(denominator(v))"
        v isa AbstractFloat && return "f$(v)"
        return "?$(typeof(v))"
    end
    h = child(t, 1)
    return (is_nil(h) ? "c[]" : "c" * _fm_codes(sym_text(h))) * "/$(nchildren(t) - 1)(" *
           join([_fm_enc(child(t, i), seen) for i in 2:nchildren(t)], ",") * ")"
end

# the swipl side: test/core_lang/test_ssu_swipl.jl's driver (consult, then every answer of each t_<id>/1, `enc`oded)
const _FM_DRIVER = raw"""
enc(T) :- enc(T, [], _).
enc(V, S0, S) :- var(V), !, ( vidx(S0, V, 0, I) -> S = S0 ; length(S0, I), append(S0, [V], S) ), format("V~w", [I]).
enc(T, S, S) :- T == [], !, write(nil).
enc(T, S, S) :- atom(T), !, atom_codes(T, Cs), format("a~w", [Cs]).
enc(T, S, S) :- string(T), !, string_codes(T, Cs), format("s~w", [Cs]).
enc(T, S, S) :- integer(T), !, format("i~w", [T]).
enc(T, S, S) :- rational(T, N, D), !, format("q~wr~w", [N, D]).
enc(T, S, S) :- float(T), !, format("f~w", [T]).
enc(T, S0, S) :- compound_name_arity(T, N, A),
    ( N == [] -> write('c[]') ; atom_codes(N, Cs), format("c~w", [Cs]) ),
    format("/~w(", [A]), encargs(1, A, T, S0, S), write(')').
encargs(I, A, _, S, S) :- I > A, !.
encargs(I, A, T, S0, S) :- arg(I, T, X), enc(X, S0, S1), ( I < A -> write(',') ; true ),
    I1 is I+1, encargs(I1, A, T, S1, S).
vidx([X|_], V, I, I) :- X == V, !.
vidx([_|Xs], V, I0, I) :- I1 is I0+1, vidx(Xs, V, I1, I).
fz_pred(N) :-
    format("~w", [N]), functor(G, N, 1),
    catch(findnsols(50, G, G, Gs), _, Gs = [exception]),
    forall(member(S, Gs), ( S == exception -> write(' exception') ; write(' '), enc(S) )), nl.
fz_run(File, Ns) :-
    catch(( consult(File), S = ok ), E, S = exc(E)),
    ( S == ok -> writeln(ok) ; S = exc(B), write('exc '), enc(B), nl ),
    forall(member(N, Ns), fz_pred(N)).
"""
function _fm_swipl_lines(
    path::String, names::Vector{String}; prelude::String=""
)::Vector{String}
    out = mktempdir() do d
        f = joinpath(d, "drv.pl")
        write(
            f,
            _FM_DRIVER * prelude * ":- initialization((fz_run('$path', [" *
            join(names, ",") * "]), halt)).\n"
        )
        read(pipeline(`swipl -q $f`; stdin=devnull, stderr=devnull), String)
    end
    return String.(split(chomp(out), '\n'; keepempty=false))
end

