# rows whose swipl answer differs and the kernel's is pinned: (id, goal, kernel's answer, swipl's answer); k01-k02: the kernel prints the C locale (D9); k03: flag (k), the numeric-argument overflow
const _FM_KNOWN = [
    (
        "k01",
        raw"""format(atom(R), "~:d|~2:d|~:D", [1234567, 1234567, 1234567])""",
        "1234567|12345.67|1_234_567",
        "1,234,567|12,345.67|1_234_567"
    ),
    (
        "k02",
        raw"""format(atom(R), "~:f|~2:e", [1234567.5, 1234567.5])""",
        "1234567.500000|1.23e+06",
        "1,234,567.500000|1.23e+06"
    ),
    # flag (k): a numeric argument past `int` (pl-fmt.c:553-556). swipl 10.1.19's `int arg2 = arg*10 + dw` wraps and its
    # overflow test `(arg2 - dw)/10 != arg` is undefined behaviour the compiler removes, so swipl prints `1` (the wrapped
    # column argument is no column at all); the port raises format('argument overflow') as the source's test says (D-0283 item 4).
    (
        "k03",
        raw"""catch(format(atom(R), "~3000000000d", [1]), error(format(R), _), true)""",
        "argument overflow",
        "1"
    )
]

"The program and cases as one file; the case predicates' names."
function _fm_file(cases)::Tuple{String, Vector{String}}
    names = ["t_$(id)" for (id, _) in cases]
    text =
        _FM_PROGRAM * join([
            "t_$(id)(R) :- catch(($g), error(SsuE, _), R = raised(SsuE)).\n" for
            (id, g) in cases
        ])
    f = joinpath(mktempdir(), "o1a.pl")
    write(f, text)
    return f, names
end

"The kernel's lines for `names` after consulting `path`, as the driver writes swipl's; the database, for the white-box tests."
function _fm_kernel(path::String, names::Vector{String})
    gd = LK.PL_global_data{_FM}()
    ld = LK.PL_local_data{_FM}(gd)
    st, ball = LK.load_file!(gd, ld, path)
    out = [st === :ok ? "ok" : "exc " * _fm_enc(ball::_FM)]
    for name in names
        proc = LK.isCurrentProcedure(sym_key(_fms(name)), 1, LK.MODULE_user(gd))
        if proc === nothing || !LK.isDefinedProcedure(gd, proc)
            push!(out, "$name undefined")
            continue
        end
        sols = String[]
        fid = LK.PL_open_foreign_frame(ld)
        a = LK.PL_new_term_refs(ld, 1)
        LK.putSlotValue!(ld, a + 1, mk_var(_FM, LK.fresh_var_keys!(1)), LK.PutVarMap())
        qid = LK.PL_open_query(
            gd, ld, nothing, LK.PL_Q_CATCH_EXCEPTION | LK.PL_Q_EXT_STATUS, proc, a
        )
        n = 0
        while (n += 1) <= 50
            rc = LK.PL_next_solution(gd, ld, qid)
            if rc == LK.PL_S_TRUE || rc == LK.PL_S_LAST
                push!(
                    sols,
                    _fm_enc(mk_expr(_FM, _FM[_fms(name), lk_answers(ld, (a:a)...)...]))
                )
                rc == LK.PL_S_LAST && break
            elseif rc == LK.PL_S_EXCEPTION
                push!(sols, "exception")
                break
            else
                break
            end
        end
        LK.PL_close_query(ld, qid)
        LK.PL_close_foreign_frame(ld, fid)
        push!(out, "$name" * join(" " .* sols))
    end
    return out, gd, ld
end

"The driver's line for the case `id` answering the atom `s`."
_fm_atomline(id::String, s::String)::String =
    "t_$id c" * _fm_codes("t_$id") * "/1(a" * _fm_codes(s) * ")"

# KNOWN DIFFERENCE (e18, "~`" with no fill character): swipl raises
# existence_error(format_character, '\0') (its atom holds the character 0, pinned above as a[0]); the
# kernel's atoms cannot (`_atom_from_text`, settled: keep refusing), so `codeToAtom` throws a
# NotPortedError before any answer. The row leaves the comparison below and is pinned by its own testset.
# Checklist: revisit with phase 2's atom table.
# e25 ("abc~", the text ends right after the tilde) is the same cause and a STABLE pin: swipl reads the NUL terminator as the
# directive character and raises existence_error(format_character, '\0') (two byte-identical swipl runs; the live check below
# compares it). e18's pin is NOT stable: after "~`" swipl reads PAST the text (`fmt->text.t[length+1]`, undefined), and one
# binary answered `not enough arguments`, another existence_error(format_character, ' ') for the same text; the pinned a[0] is
# what one build read. e18 therefore stays out of the live comparison (`_fm_not_unstable`), as its kernel answer is a refusal.
const _FM_E18 = "t_e18"
const _FM_E25 = "t_e25"
_fm_not_e18(l) = !startswith(l, _FM_E18 * " ") && !startswith(l, _FM_E25 * " ")
_fm_not_unstable(l) = !startswith(l, _FM_E18 * " ")

@testset "format/2,3 as swipl's (f01-f74, e01-e19)" begin
    f, names = _fm_file(filter(c -> c[1] != "e18" && c[1] != "e25", _FM_CASES))
    kl, _, _ = _fm_kernel(f, names)
    pinned = filter(_fm_not_e18, _FM_PINNED)
    @test length(pinned) == length(_FM_PINNED) - 2
    @test length(kl) == length(pinned)
    for (k, p) in zip(kl, pinned)
        k == p || println(stderr, "  ours  ", k, "\n  swipl ", p)
        @test k == p
    end
    # not vacuous: both sides hold answers, the error rows raised, the column rows pad with spaces (code 32), the call-back
    # rows hold the call-backs' output (hello: 104,101,108,108,111), the failing call-back row has no answer
    @test length(kl) > 80 && !any(isempty, kl)
    @test count(l -> occursin("c[114,97,105,115,101,100]", l), _FM_PINNED) >= 15           # raised(…)
    @test count(l -> occursin("32,32,32", l), _FM_PINNED) >= 12                              # column padding
    @test count(l -> occursin("104,101,108,108,111", l), _FM_PINNED) >= 6                   # hello_out through ~@
    @test _FM_PINNED[findfirst(l -> startswith(l, "t_f69"), _FM_PINNED)] == "t_f69"        # the failing call-back
    @test any(
        l ->
            startswith(l, "t_f70 ") &&
            occursin("c[99,97,117,103,104,116]/1(a[98,111,111,109])", l),
        _FM_PINNED
    )  # caught(boom)
end

@testset "known differences on the kernel: the C locale (D9, k01-k02) and the numeric-argument overflow (flag k, k03), swipl's answer noted per row" begin
    f, names = _fm_file([(id, g) for (id, g, _, _) in _FM_KNOWN])
    kl, _, _ = _fm_kernel(f, names)
    @test length(kl) == length(_FM_KNOWN) + 1
    for ((id, g, ours, swipl_says), k) in zip(_FM_KNOWN, kl[2:end])
        @test k == _fm_atomline(id, ours)
        @test ours != swipl_says                                                        # the row records a known difference
    end
    # swipl's own answers, live: grouped by the locale
    swipl = get(ENV, "LOGICKERNEL_NO_SWIPL", "") == "1" ? nothing : Sys.which("swipl")
    if swipl !== nothing
        f, names = _fm_file([(id, g) for (id, g, _, _) in _FM_KNOWN])
        # the locale is set in the driver (the machine's LANG decides otherwise: CI's C locale groups nothing, a developer's
        # en_US groups with ","; the rows' swipl answers are the grouped ones, measured on swipl 10.1.19)
        loc = ":- locale_create(L, 'C', [thousands_sep(','), decimal_point('.'), grouping([repeat(3)])]), set_locale(L).\n"
        @test _fm_swipl_lines(f, names; prelude=loc)[2:end] ==
            [_fm_atomline(id, sw) for (id, _, _, sw) in _FM_KNOWN]
    end
end

@testset "e18, e25 on the kernel: swipl's format_character '\\0' cannot be an atom here (known difference)" begin
    for id in ("e18", "e25")
        @test any(l -> startswith(l, "t_$id ") && endswith(l, "a[0])))"), _FM_PINNED)  # swipl's answer
        f, names = _fm_file(filter(c -> c[1] == id, _FM_CASES))
        err = try
            _fm_kernel(f, names)
            nothing
        catch e
            e
        end
        @test err isa LK.NotPortedError                                                 # ours: refused, not misread
        @test occursin("character 0", err.what)
    end
end

# KNOWN DIFFERENCE: C undefined behaviour (size_t underflow / reads past the buffer). Rows whose swipl answer is not reproducible,
# so no live comparison: (id, goal, the kernel's answer, what swipl 10.1.19 does, observed by the reader of FMT-READ.md in the audit channel).
#   u01 `~-1s`: pl-fmt.c:784-806 sets `arg = 0` for a negative count but leaves `txt.length` whole, then pads
#       `for (size_t i = arg - txt.length; ...)`, an unsigned underflow: swipl prints `abc` and then spaces without end (no `|`).
#   u02 `~25d` of 2**64 (20 digits): formatInteger's V_MPZ branch reads before the digit buffer when the fraction-digit count
#       exceeds the digit count: swipl prints stack garbage, different bytes on every run (3 runs, 3 answers); the kernel pads zeros.
const _FM_UB = [
    ("u01", raw"""format(atom(R), "~-1s|", [abc])""", "abc|"),
    (
        "u02",
        raw"""format(atom(R), "~25d", [18446744073709551616])""",
        "0.0000018446744073709551616"
    )
]

@testset "C undefined behaviour on the kernel (u01 ~-1s, u02 ~Nd past a bignum's digits): the kernel's exact answer, swipl's not reproducible" begin
    f, names = _fm_file([(id, g) for (id, g, _) in _FM_UB])
    kl, _, _ = _fm_kernel(f, names)
    @test length(kl) == length(_FM_UB) + 1
    for ((id, g, ours), k) in zip(_FM_UB, kl[2:end])
        @test k == _fm_atomline(id, ours)
    end
end

# D9: format_predicate/2 is refused by name (pl-fmt.c :249-325 would add the directive to GD->format.predicates; swipl succeeds).
@testset "d09 format_predicate/2 on the kernel: refused by name, swipl succeeds (known difference)" begin
    goal = raw"""format_predicate(x, fp_x(_, _)), R = done"""
    f, names = _fm_file([("d09", goal)])
    err = try
        _fm_kernel(f, names)
        nothing
    catch e
        e
    end
    @test err isa LK.NotPortedError
    @test occursin("format_predicate", err.what)
    swipl = get(ENV, "LOGICKERNEL_NO_SWIPL", "") == "1" ? nothing : Sys.which("swipl")
    if swipl !== nothing
        @test _fm_swipl_lines(f, names)[2:end] == [_fm_atomline("d09", "done")]
    end
end

@testset "the pins are swipl's (live, when swipl is on PATH)" begin
    swipl = get(ENV, "LOGICKERNEL_NO_SWIPL", "") == "1" ? nothing : Sys.which("swipl")
    @test length(_FM_PINNED) == length(_FM_CASES) + 1
    if swipl === nothing
        @info "O1A LIVE CHECK NOT RUN: `swipl` is not on PATH here. It runs in tools/run_tests.sh and CI."
    else
        f, names = _fm_file(_FM_CASES)
        @test filter(_fm_not_unstable, _fm_swipl_lines(f, names)) ==
            filter(_fm_not_unstable, _FM_PINNED)
    end
end
